from PIL import Image
import numpy as np

# Open and convert image to grayscale
img = Image.open('ctf_files/short-circuit.jpg')
gray = img.convert('L')
data = np.array(gray)

# Function to find potential circuit elements
def find_circuit_elements():
    h, w = data.shape
    elements = []

    # Look for distinct elements that could be circuit components
    threshold = 50  # Threshold for black pixels
    min_size = 10   # Minimum size to consider

    for y in range(0, h, min_size):
        for x in range(0, w, min_size):
            region = data[y:min(y+min_size, h), x:min(x+min_size, w)]
            if np.mean(region) < threshold:
                elements.append((x, y))

    return elements

# Function to analyze vertical and horizontal lines
def analyze_lines():
    h, w = data.shape

    # Look for horizontal lines
    horizontal_lines = []
    vertical_lines = []

    # Parameters for line detection
    min_length = 20
    threshold = 50

    # Detect horizontal lines
    for y in range(h):
        line_start = None
        for x in range(w):
            if data[y,x] < threshold:
                if line_start is None:
                    line_start = x
            elif line_start is not None:
                if x - line_start > min_length:
                    horizontal_lines.append((line_start, y, x, y))
                line_start = None

    # Detect vertical lines
    for x in range(w):
        line_start = None
        for y in range(h):
            if data[y,x] < threshold:
                if line_start is None:
                    line_start = y
            elif line_start is not None:
                if y - line_start > min_length:
                    vertical_lines.append((x, line_start, x, y))
                line_start = None

    return len(horizontal_lines), len(vertical_lines)

# Find circuit elements
elements = find_circuit_elements()
print(f"Found {len(elements)} potential circuit elements")

# Analyze lines
h_lines, v_lines = analyze_lines()
print(f"Found {h_lines} horizontal lines and {v_lines} vertical lines")

# Look for repeating patterns
def find_repeating_patterns():
    h, w = data.shape
    pattern_size = 30  # Adjust based on expected component size
    patterns = []

    for y in range(0, h-pattern_size, pattern_size):
        for x in range(0, w-pattern_size, pattern_size):
            pattern = data[y:y+pattern_size, x:x+pattern_size]
            # Check if pattern has significant black pixels
            if np.sum(pattern < threshold) > pattern_size*pattern_size/4:
                patterns.append((x,y))

    return patterns

patterns = find_repeating_patterns()
print(f"Found {len(patterns)} potential repeating patterns")

from PIL import Image
import numpy as np

def analyze_circuit_patterns():
    # Open and load the image
    img = Image.open('ctf_files/short-circuit.jpg')
    img_data = np.array(img)

    # Convert to binary (threshold)
    binary = (img_data > 128).astype(int)

    # Parameters
    segment_height = 26
    num_segments = 112

    # Look for circuit traces (continuous paths)
    patterns = []

    # Scan horizontally first, then vertically
    for y in range(0, binary.shape[0]-segment_height+1):
        row_patterns = []
        for x in range(0, binary.shape[1]):
            segment = binary[y:y+segment_height, x]

            # Check for breaks in the circuit trace
            if np.sum(segment) > 0:  # If there's any white pixels
                # Check for discontinuity in the middle
                middle = segment[segment_height//3:-segment_height//3]
                if np.any(middle == 0):
                    row_patterns.append('0')
                else:
                    row_patterns.append('1')

        if row_patterns:
            patterns.extend(row_patterns)
            if len(patterns) >= num_segments:
                patterns = patterns[:num_segments]
                break

    if patterns:
        binary_str = ''.join(patterns)
        print(f"Found {len(patterns)} patterns")
        print(f"Binary: {binary_str}")

        # Try different groupings (7-bit, 8-bit)
        for bits in [7, 8]:
            print(f"\nTrying {bits}-bit grouping:")
            ascii_text = ""
            for i in range(0, len(binary_str), bits):
                if i + bits <= len(binary_str):
                    char_bits = binary_str[i:i+bits]
                    try:
                        char_code = int(char_bits, 2)
                        char = chr(char_code)
                        if char.isprintable():
                            ascii_text += char
                        else:
                            ascii_text += '.'
                    except:
                        ascii_text += '?'
            print(f"ASCII: {ascii_text}")

        # Try reversing the bits
        binary_rev = binary_str[::-1]
        print("\nReversed bits:")
        for i in range(0, len(binary_rev), 8):
            if i + 8 <= len(binary_rev):
                char_bits = binary_rev[i:i+8]
                try:
                    char_code = int(char_bits, 2)
                    char = chr(char_code)
                    if char.isprintable():
                        print(f"{char}", end='')
                except:
                    pass

analyze_circuit_patterns()

from PIL import Image
import numpy as np

def analyze_vertical_segments():
    # Open and load the image
    img = Image.open('ctf_files/short-circuit.jpg')
    # Convert to grayscale if it's not already
    if img.mode != 'L':
        img = img.convert('L')
    img_data = np.array(img)

    # Parameters
    segment_height = 26
    num_segments = 112
    threshold = 128

    # Convert to binary
    binary = (img_data > threshold).astype(int)

    # Find vertical traces
    patterns = []
    height, width = binary.shape

    # Scan for vertical segments
    for x in range(width):
        for y in range(0, height - segment_height + 1, segment_height):
            segment = binary[y:y+segment_height, x]

            # Check if this is a vertical trace
            if np.sum(segment) > segment_height * 0.7:  # More than 70% white pixels
                # Check for break in middle third
                mid_start = segment_height // 3
                mid_end = segment_height - mid_start
                middle = segment[mid_start:mid_end]

                # If there's a break in the middle, it's a 0, otherwise 1
                if np.min(middle) == 0:
                    patterns.append('0')
                else:
                    patterns.append('1')

                if len(patterns) >= num_segments:
                    break

        if len(patterns) >= num_segments:
            break

    if patterns:
        patterns = patterns[:num_segments]  # Ensure exactly 112 patterns
        binary_str = ''.join(patterns)
        print(f"Found {len(patterns)} patterns")
        print(f"Binary: {binary_str}")

        # Try to decode as 8-bit ASCII
        print("\n8-bit ASCII decoding:")
        for i in range(0, len(binary_str), 8):
            if i + 8 <= len(binary_str):
                byte = binary_str[i:i+8]
                try:
                    char = chr(int(byte, 2))
                    if char.isprintable():
                        print(char, end='')
                    else:
                        print('.', end='')
                except:
                    print('?', end='')

        # Try reversed bits
        print("\n\nReversed 8-bit ASCII decoding:")
        binary_rev = binary_str[::-1]
        for i in range(0, len(binary_rev), 8):
            if i + 8 <= len(binary_rev):
                byte = binary_rev[i:i+8]
                try:
                    char = chr(int(byte, 2))
                    if char.isprintable():
                        print(char, end='')
                    else:
                        print('.', end='')
                except:
                    print('?', end='')

        # Try as 7-bit ASCII
        print("\n\n7-bit ASCII decoding:")
        for i in range(0, len(binary_str), 7):
            if i + 7 <= len(binary_str):
                bits = binary_str[i:i+7]
                try:
                    char = chr(int(bits, 2))
                    if char.isprintable():
                        print(char, end='')
                    else:
                        print('.', end='')
                except:
                    print('?', end='')

analyze_vertical_segments()

from PIL import Image
import numpy as np

def find_thin_patterns(img_array):
    height, width, _ = img_array.shape
    patterns = []

    # Look at first 112 rows
    for y in range(112):
        row = img_array[y,:,0]
        # Get black/white transitions
        transitions = []
        current = 1 if row[0] > 128 else 0
        for i in range(1, width):
            if (row[i] > 128) != current:
                transitions.append(i)
                current = not current
        patterns.append(transitions)

    return patterns

def analyze_transitions(patterns):
    # Convert transition patterns to distances
    distances = []
    for transitions in patterns:
        if len(transitions) > 1:
            dists = []
            for i in range(len(transitions)-1):
                dist = transitions[i+1] - transitions[i]
                dists.append(dist)
            distances.append(dists)

    # Look for common distances that might encode flag
    distance_counts = {}
    for dists in distances:
        for d in dists:
            if d not in distance_counts:
                distance_counts[d] = 0
            distance_counts[d] += 1

    # Sort distances by frequency
    common_distances = sorted([(d, c) for d, c in distance_counts.items()], 
                            key=lambda x: x[1], reverse=True)

    # Try to decode using most common distances
    for dist, count in common_distances[:20]:
        if dist >= 32 and dist <= 126:  # ASCII printable range
            print(f"Distance {dist} ({chr(dist)}) appears {count} times")

def decode_thin_lines(patterns):
    # Convert each pattern to bits based on different thresholds
    for threshold in range(1, 6):
        bits = []
        for transitions in patterns:
            row_bits = ''
            for i in range(len(transitions)-1):
                dist = transitions[i+1] - transitions[i]
                row_bits += '1' if dist >= threshold else '0'
            if row_bits:
                bits.append(row_bits)

        # Try to decode the bits as ASCII
        if bits:
            binary = ''.join(bits)
            # Try different groupings and offsets
            for size in [7, 8]:
                for offset in range(size):
                    try:
                        # Forward
                        text = ''
                        for i in range(offset, len(binary)-size+1, size):
                            val = int(binary[i:i+size], 2)
                            if 32 <= val <= 126:
                                text += chr(val)
                        if text and ('flag{' in text or '{' in text):
                            print(f"Threshold {threshold}, {size}-bit, offset {offset}:")
                            print(text)

                        # Reverse
                        binary_rev = binary[::-1]
                        text = ''
                        for i in range(offset, len(binary_rev)-size+1, size):
                            val = int(binary_rev[i:i+size], 2)
                            if 32 <= val <= 126:
                                text += chr(val)
                        if text and ('flag{' in text or '{' in text):
                            print(f"Threshold {threshold}, {size}-bit reverse, offset {offset}:")
                            print(text)
                    except:
                        continue

def vertical_analysis(img_array):
    height, width, _ = img_array.shape
    # Look for vertical patterns in first 112 rows
    for x in range(width):
        column = img_array[:112,x,0]
        transitions = []
        current = column[0] > 128
        for y in range(1, 112):
            if (column[y] > 128) != current:
                transitions.append(y)
                current = not current
        if len(transitions) > 0:
            print(f"Column {x} transitions: {transitions}")
            # Check if transitions form ASCII pattern
            if len(transitions) > 1:
                for i in range(len(transitions)-1):
                    diff = transitions[i+1] - transitions[i]
                    if 32 <= diff <= 126:
                        print(f"Possible ASCII at column {x}: {chr(diff)}")

# Load and process image
img = Image.open('/home/ctfplayer/ctf_files/short-circuit.jpg')
img_array = np.array(img)

# Find patterns in thin lines
patterns = find_thin_patterns(img_array)

print("Analyzing horizontal patterns...")
analyze_transitions(patterns)

print("\nTrying to decode bits from thin lines...")
decode_thin_lines(patterns)

print("\nAnalyzing vertical patterns...")
vertical_analysis(img_array)

# Also try looking at pairs of transitions
print("\nAnalyzing transition pairs...")
for i, transitions in enumerate(patterns):
    if len(transitions) >= 2:
        for j in range(len(transitions)-1):
            pair = (transitions[j], transitions[j+1])
            # Try various encodings of the pair
            try:
                # XOR of positions
                xor_val = pair[0] ^ pair[1]
                if 32 <= xor_val <= 126:
                    print(f"Line {i} pair XOR: {chr(xor_val)}")

                # Distance as char
                dist = pair[1] - pair[0]
                if 32 <= dist <= 126:
                    print(f"Line {i} distance: {chr(dist)}")

                # Average as char
                avg = (pair[0] + pair[1]) // 2
                if 32 <= avg <= 126:
                    print(f"Line {i} average: {chr(avg)}")
            except:
                continue

# Look for sequences that could form flag characters
print("\nLooking for flag patterns...")
flag_chars = set("flag{}")
possible_flag_sections = []

for i, transitions in enumerate(patterns):
    if len(transitions) >= 2:
        for j in range(len(transitions)-1):
            dist = transitions[j+1] - transitions[j]
            if chr(dist) in flag_chars:
                nearby_chars = []
                # Look at nearby transitions for rest of flag
                for k in range(max(0, j-5), min(len(transitions)-1, j+6)):
                    d = transitions[k+1] - transitions[k]
                    if 32 <= d <= 126:
                        nearby_chars.append(chr(d))
                if nearby_chars:
                    print(f"Line {i}, potential flag section: {''.join(nearby_chars)}")
                    possible_flag_sections.append(nearby_chars)
